import math
import os
import importlib.util
import sysconfig
import subprocess
import struct
import ctypes
import torch
import triton
import triton.language as tl
from triton.runtime import driver

torch.set_grad_enabled(False)


@triton.jit
def _inv_freq_kernel(out_ptr, log_theta, HEAD_DIM: tl.constexpr, N: tl.constexpr):
    i = tl.arange(0, N)
    exponent = (2.0 * i.to(tl.float32)) / float(HEAD_DIM)
    inv_freq = tl.exp2(-exponent * log_theta)
    tl.store(out_ptr + i, inv_freq)


_buf = torch.empty(64, dtype=torch.float32, device='cuda')
_inv_freq_kernel[(1,)](_buf, 0.0, HEAD_DIM=128, N=64, num_warps=1)
torch.cuda.synchronize()

_dev = driver.active.get_current_device()
_kc, _, _, _, _binder = _inv_freq_kernel.device_caches[_dev]
_compiled = _kc[next(iter(_kc))]
_func_handle = int(_compiled.function)

_AQL_C_SOURCE = r"""#define PY_SSIZE_T_CLEAN
