    unsigned long long queue_ptr, ka_base, out_ptr, kernel_object;
    unsigned int private_seg, group_seg; PyObject* buf;
    if (!PyArg_ParseTuple(args, "KKKIIKO", &queue_ptr, &out_ptr, &kernel_object,
                         &private_seg, &group_seg, &ka_base, &buf)) return NULL;
    uint8_t* q = (uint8_t*)queue_ptr;
    _qbase = *(void**)(q + 8);
    _doorbell_val = *(uint64_t*)(q + 16);
    _qsize = *(uint32_t*)(q + 24);
    _widx_ptr = (volatile uint64_t*)(q + 56);
    _ka_buf = (char*)ka_base;
    Py_XDECREF(_buf); _buf = buf; Py_INCREF(_buf);
    *(uint64_t*)(_ka_buf + 0) = out_ptr;
    *(float*)(_ka_buf + 8) = 0.0f;
    void* hsa = dlopen("libhsa-runtime64.so.1", RTLD_NOW | RTLD_GLOBAL);
    if (!hsa) hsa = dlopen("libhsa-runtime64.so", RTLD_NOW | RTLD_GLOBAL);
    if (!hsa) { PyErr_SetString(PyExc_RuntimeError, "hsa"); return NULL; }
    _sig_store = (hsa_sig_store_t)dlsym(hsa, "hsa_signal_store_screlease");
    if (!_sig_store) { PyErr_SetString(PyExc_RuntimeError, "sig"); return NULL; }
    memset(_pkt, 0, 64);
    uint16_t* p16 = (uint16_t*)_pkt;
    uint32_t* p32 = (uint32_t*)_pkt;
    uint64_t* p64 = (uint64_t*)_pkt;
    /* No barrier (bit 8=0), agent-scope fences (1<<9, 1<<11) */
    p16[0] = (uint16_t)((2u<<0)|(0u<<8)|(1u<<9)|(1u<<11));
    p16[1]=1; p16[2]=64; p16[3]=1; p16[4]=1; p16[5]=0;
    p32[3]=64; p32[4]=1; p32[5]=1; p32[6]=private_seg; p32[7]=group_seg;
    p64[4]=kernel_object; p64[5]=(uint64_t)(uintptr_t)_ka_buf; p64[6]=0; p64[7]=0;
    for (uint32_t _fi = 0; _fi < _qsize; _fi++)
        __builtin_memcpy((char*)_qbase + _fi * 64, _pkt, 64);
    __atomic_thread_fence(__ATOMIC_SEQ_CST);
    Py_RETURN_NONE;
}

static PyObject* py_run(PyObject* self, PyObject* arg) {
    *(float*)(_ka_buf + 8) = log2f((float)PyFloat_AS_DOUBLE(arg));
    uint64_t widx = *_widx_ptr;
    *_widx_ptr = widx + 1;
    _sig_store(_doorbell_val, (int64_t)(widx + 1));
    Py_INCREF(_buf);
    return _buf;
}

static PyMethodDef methods[] = {
    {"setup", py_setup, METH_VARARGS, NULL},
    {"run", py_run, METH_O, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef module = {
    PyModuleDef_HEAD_INIT, "aqlkernel", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_aqlkernel(void) { return PyModule_Create(&module); }
