import os
import torch
from torch.utils.cpp_extension import load_inline

os.environ.setdefault('PYTORCH_ROCM_ARCH', 'gfx950')
os.environ.setdefault('TORCH_EXTENSIONS_DIR', '/tmp/torch_extensions_hip')

_hip_source = r"""
#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>
#include <ATen/cuda/CUDAContext.h>

#define WF_SIZE 64
using f32x4 = float __attribute__((ext_vector_type(4)));

template<int BLOCK_SIZE, int H, bool USE_NT>
__global__ void post_norm_residual_kernel(
    const __hip_bfloat16* __restrict__ x,
    const __hip_bfloat16* __restrict__ res,
    const __hip_bfloat16* __restrict__ w,
    __hip_bfloat16* __restrict__ out,
    float eps)
{
    constexpr int VEC = 8;
    constexpr int VECS_PER_THREAD = H / (BLOCK_SIZE * VEC);
    constexpr int NUM_WF = BLOCK_SIZE / WF_SIZE;
    constexpr int ELEMS = VECS_PER_THREAD * VEC;

    const int row = blockIdx.x;
    const int tid = threadIdx.x;
    const int wf_id = tid / WF_SIZE;
    const int lane = tid % WF_SIZE;

    const __hip_bfloat16* x_row = x + (size_t)row * H;
    const __hip_bfloat16* res_row = res + (size_t)row * H;
    __hip_bfloat16* out_row = out + (size_t)row * H;

    float x_vals[ELEMS];
    float res_vals[ELEMS];
    float sum_sq = 0.0f;

    #pragma unroll
    for (int v = 0; v < VECS_PER_THREAD; v++) {
        int base = (v * BLOCK_SIZE + tid) * VEC;
        f32x4 x_v, res_v;
        if constexpr (USE_NT) {
            x_v = __builtin_nontemporal_load(reinterpret_cast<const f32x4*>(x_row + base));
            res_v = __builtin_nontemporal_load(reinterpret_cast<const f32x4*>(res_row + base));
        } else {
            x_v = *reinterpret_cast<const f32x4*>(x_row + base);
            res_v = *reinterpret_cast<const f32x4*>(res_row + base);
        }
        __hip_bfloat162* x_bf2 = reinterpret_cast<__hip_bfloat162*>(&x_v);
        __hip_bfloat162* res_bf2 = reinterpret_cast<__hip_bfloat162*>(&res_v);
        #pragma unroll
        for (int i = 0; i < 4; i++) {
            float2 x_f2 = __bfloat1622float2(x_bf2[i]);
            float2 res_f2 = __bfloat1622float2(res_bf2[i]);
            int idx = v * VEC + i * 2;
            x_vals[idx] = x_f2.x;
            x_vals[idx + 1] = x_f2.y;
            res_vals[idx] = res_f2.x;
            res_vals[idx + 1] = res_f2.y;
            sum_sq += x_f2.x * x_f2.x + x_f2.y * x_f2.y;
        }
    }

    #pragma unroll
    for (int mask = WF_SIZE / 2; mask > 0; mask >>= 1)
        sum_sq += __shfl_xor(sum_sq, mask, WF_SIZE);

    __shared__ float wf_sums[NUM_WF];
    if (lane == 0) wf_sums[wf_id] = sum_sq;
    __syncthreads();

    float total = 0.0f;
    #pragma unroll
    for (int i = 0; i < NUM_WF; i++) total += wf_sums[i];
    float rstd = rsqrtf(total / (float)H + eps);

    #pragma unroll
    for (int v = 0; v < VECS_PER_THREAD; v++) {
        int base = (v * BLOCK_SIZE + tid) * VEC;
        f32x4 w_v = *reinterpret_cast<const f32x4*>(w + base);
        __hip_bfloat162* w_bf2 = reinterpret_cast<__hip_bfloat162*>(&w_v);
        f32x4 out_v;
        __hip_bfloat162* out_bf2 = reinterpret_cast<__hip_bfloat162*>(&out_v);
        #pragma unroll
        for (int i = 0; i < 4; i++) {
            float2 w_f2 = __bfloat1622float2(w_bf2[i]);
            int idx = v * VEC + i * 2;
            float norm_x = w_f2.x * (x_vals[idx] * rstd);
            float norm_y = w_f2.y * (x_vals[idx + 1] * rstd);
            out_bf2[i] = __float22bfloat162_rn(
                make_float2(res_vals[idx] + norm_x, res_vals[idx + 1] + norm_y));
        }
        *reinterpret_cast<f32x4*>(out_row + base) = out_v;
    }
}

torch::Tensor post_norm_residual(torch::Tensor x, torch::Tensor res,
                                 torch::Tensor w, double eps) {
    int M = x.size(0) * x.size(1);
    int H = x.size(2);
    auto out = torch::empty_like(res);
    auto stream = at::cuda::getCurrentCUDAStream().stream();

    auto xptr = reinterpret_cast<const __hip_bfloat16*>(x.data_ptr());
    auto rptr = reinterpret_cast<const __hip_bfloat16*>(res.data_ptr());
    auto wptr = reinterpret_cast<const __hip_bfloat16*>(w.data_ptr());
    auto optr = reinterpret_cast<__hip_bfloat16*>(out.data_ptr());
    float feps = (float)eps;

    if (M >= 16384) {
        post_norm_residual_kernel<256, 4096, true><<<M, 256, 0, stream>>>(
            xptr, rptr, wptr, optr, feps);
    } else {
        post_norm_residual_kernel<256, 4096, false><<<M, 256, 0, stream>>>(
            xptr, rptr, wptr, optr, feps);
    }
    return out;
}
"""

_cpp_source = """
