_HIP_SRC = r"""
#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>

using f32x4 = float __attribute__((ext_vector_type(4)));

template <int BLOCK>
__global__ void rmsnorm_residual_kernel(
    const __hip_bfloat16* __restrict__ sub,
    const __hip_bfloat16* __restrict__ res,
    const __hip_bfloat16* __restrict__ wt,
    __hip_bfloat16* __restrict__ out,
    int H, float eps
) {
    constexpr int VEC = 8;
    constexpr int HIDDEN = 4096;
    constexpr int VPT = HIDDEN / (BLOCK * VEC);
    constexpr int WAVES = BLOCK / 64;

    int row = blockIdx.x;
    int tid = threadIdx.x;
    int wave_id = tid / 64;
    int lane_id = tid % 64;

    const __hip_bfloat16* row_sub = sub + (size_t)row * H;
    const __hip_bfloat16* row_res = res + (size_t)row * H;
    __hip_bfloat16* row_out = out + (size_t)row * H;

    __shared__ __hip_bfloat16 shared_wt[HIDDEN];
    __shared__ float partials[WAVES];

    f32x4 svecs[VPT], rvecs[VPT];
    #pragma unroll
    for (int v = 0; v < VPT; v++) {
        int offset = v * BLOCK * VEC + tid * VEC;
        svecs[v] = __builtin_nontemporal_load(reinterpret_cast<const f32x4*>(row_sub + offset));
        rvecs[v] = __builtin_nontemporal_load(reinterpret_cast<const f32x4*>(row_res + offset));
        *reinterpret_cast<f32x4*>(&shared_wt[offset]) = *reinterpret_cast<const f32x4*>(wt + offset);
    }

    float sum_sq = 0.0f;
    #pragma unroll
    for (int v = 0; v < VPT; v++) {
        __hip_bfloat16* sb = reinterpret_cast<__hip_bfloat16*>(&svecs[v]);
        #pragma unroll
        for (int i = 0; i < VEC; i++) {
