            sum_sq += val * val;
        }
    }

    #pragma unroll
    for (int s = 32; s > 0; s >>= 1) sum_sq += __shfl_down(sum_sq, s, 64);

    if (lane_id == 0) partials[wave_id] = sum_sq;
    __syncthreads();

    float total = 0.0f;
    #pragma unroll
    for (int w = 0; w < WAVES; w++) total += partials[w];
    float rstd = rsqrtf(total / (float)HIDDEN + eps);

    #pragma unroll
    for (int v = 0; v < VPT; v++) {
        int offset = v * BLOCK * VEC + tid * VEC;
        f32x4 out_vec;
        __hip_bfloat16* sb = reinterpret_cast<__hip_bfloat16*>(&svecs[v]);
        __hip_bfloat16* rb = reinterpret_cast<__hip_bfloat16*>(&rvecs[v]);
        __hip_bfloat16* wb = &shared_wt[offset];
        __hip_bfloat16* ob = reinterpret_cast<__hip_bfloat16*>(&out_vec);
