struct alignas(16) Bf16x8 {
    __hip_bfloat162 pair[4];
};

constexpr int kWarp = 64;
constexpr int kRowsPerBlock = 8;

__device__ __forceinline__ float warp_reduce(float value) {
    for (int offset = warpSize / 2; offset > 0; offset /= 2)
        value += __shfl_down(value, offset);
    return value;
}

__global__ void rmsnorm_kernel(const __hip_bfloat16* __restrict__ input,
                               const __hip_bfloat16* __restrict__ weight,
                               __hip_bfloat16* __restrict__ output,
                               float epsilon, int rows) {
    constexpr int kHidden = 512;
    const int row = blockIdx.x * kRowsPerBlock + threadIdx.x / kWarp;
    const int lane = threadIdx.x % kWarp;
    if (row >= rows) return;

    const Bf16x8 row_input = reinterpret_cast<const Bf16x8*>(
        input + static_cast<int64_t>(row) * kHidden + lane * 8)[0];
    const Bf16x8 weight_values =
        reinterpret_cast<const Bf16x8*>(weight + lane * 8)[0];
    float2 values[4];
    float sum = 0.0f;

    #pragma unroll
    for (int index = 0; index < 4; ++index) {
        values[index] = __bfloat1622float2(row_input.pair[index]);
        sum += values[index].x * values[index].x +
               values[index].y * values[index].y;
    }
    sum = warp_reduce(sum);
    sum = __shfl(sum, 0);
    const float scale = rsqrtf(sum / kHidden + epsilon);
    Bf16x8 result;

    #pragma unroll
    for (int index = 0; index < 4; ++index) {
        const float2 weight_value =
            __bfloat1622float2(weight_values.pair[index]);
        result.pair[index].x = __float2bfloat16(
            values[index].x * scale * weight_value.x);
        result.pair[index].y = __float2bfloat16(
            values[index].y * scale * weight_value.y);
    }
    reinterpret_cast<Bf16x8*>(
        output + static_cast<int64_t>(row) * kHidden + lane * 8)[0] = result;
}

void rmsnorm(torch::Tensor input, torch::Tensor weight, torch::Tensor output,
             double epsilon) {
    const int rows = input.numel() / 512;
    hipLaunchKernelGGL(rmsnorm_kernel,
                       dim3((rows + kRowsPerBlock - 1) / kRowsPerBlock),
                       dim3(kWarp * kRowsPerBlock), 0,
                       at::cuda::getCurrentHIPStream(),
                       reinterpret_cast<const __hip_bfloat16*>(input.data_ptr()),
                       reinterpret_cast<const __hip_bfloat16*>(weight.data_ptr()),
                       reinterpret_cast<__hip_bfloat16*>(output.data_ptr()),
                       static_cast<float>(epsilon), rows);
}

