                                    torch::Tensor layernorm_weight,
                                    torch::Tensor projection_weight,
                                    double epsilon) {
    torch::NoGradGuard no_grad;
    const int64_t batch_size = compressed_kv.size(0);
    const int64_t seq_len = compressed_kv.size(1);
    const int64_t hidden = compressed_kv.size(2);
    const int64_t rows = batch_size * seq_len;
    const int64_t expanded_dim = projection_weight.size(0);

    torch::Tensor workspace = torch::empty(
        {rows * (hidden + expanded_dim)}, compressed_kv.options());
    torch::Tensor normalized_kv = workspace
        .narrow(0, 0, rows * hidden)
        .view({rows, hidden});
    rmsnorm(compressed_kv.reshape({rows, hidden}), layernorm_weight,
            normalized_kv, epsilon);

    torch::Tensor expanded_kv = workspace
        .narrow(0, rows * hidden, rows * expanded_dim)
        .view({rows, expanded_dim});
    at::mm_out(expanded_kv, normalized_kv, projection_weight.t());

    torch::Tensor kv = expanded_kv.view({batch_size, seq_len, 128, 256})
                          .transpose(1, 2);
    return {kv.slice(3, 0, 128), kv.slice(3, 128, 256)};
}
