  const f32x4* hidden_vectors = reinterpret_cast<const f32x4*>(hidden);
  const f32x4* residual_vectors = reinterpret_cast<const f32x4*>(residual);
  const f32x4* weight_vectors = reinterpret_cast<const f32x4*>(weight);
  f32x4* output_vectors = reinterpret_cast<f32x4*>(output);

  float x[kVectorsPerThread * 8];
  float sum_squares = 0.0f;

#pragma unroll
  for (int vector = 0; vector < kVectorsPerThread; ++vector) {
    const int index = vector_base + threadIdx.x + vector * kBlockThreads;
    const f32x4 hidden_vector = hidden_vectors[index];
    const f32x4 residual_vector = residual_vectors[index];
    const __hip_bfloat162* hidden_pair =
        reinterpret_cast<const __hip_bfloat162*>(&hidden_vector);
    const __hip_bfloat162* residual_pair =
        reinterpret_cast<const __hip_bfloat162*>(&residual_vector);

#pragma unroll
    for (int pair = 0; pair < 4; ++pair) {
      const int offset = vector * 8 + pair * 2;
      x[offset] = __bfloat162float(hidden_pair[pair].x) +
                  __bfloat162float(residual_pair[pair].x);
      x[offset + 1] = __bfloat162float(hidden_pair[pair].y) +
                      __bfloat162float(residual_pair[pair].y);
      sum_squares += x[offset] * x[offset] + x[offset + 1] * x[offset + 1];
    }
  }

  sum_squares = __reduce_add_sync(0xffffffffffffffffULL, sum_squares);
  const float inv_rms = rsqrtf(sum_squares / kHiddenSize + 1.0e-6f);

#pragma unroll
  for (int vector = 0; vector < kVectorsPerThread; ++vector) {
    const int index = vector_base + threadIdx.x + vector * kBlockThreads;
    const f32x4 weight_vector = weight_vectors[threadIdx.x + vector * kBlockThreads];
    const __hip_bfloat162* weight_pair =
