  const int row = wave_id / N;
  const int col = wave_id % N;
  const __half* a_row = A + static_cast<int64_t>(row) * K;
  const __half* b_row = B + static_cast<int64_t>(col) * K;
  float acc = 0.0f;

  for (int base = 0; base < K; base += 512) {
    const int offset = base + lane * 8;
    const uint4 a_raw = *reinterpret_cast<const uint4*>(a_row + offset);
    const uint4 b_raw = *reinterpret_cast<const uint4*>(b_row + offset);
    const __half2* a_half = reinterpret_cast<const __half2*>(&a_raw);
    const __half2* b_half = reinterpret_cast<const __half2*>(&b_raw);
    #pragma unroll
    for (int pair = 0; pair < 4; ++pair) {
      const float2 a = __half22float2(a_half[pair]);
      const float2 b = __half22float2(b_half[pair]);
      acc += a.x * b.x + a.y * b.y;
    }
  }

  acc += __shfl_xor(acc, 32, 64);
  acc += __shfl_xor(acc, 16, 64);
  acc += __shfl_xor(acc, 8, 64);
  acc += __shfl_xor(acc, 4, 64);
  acc += __shfl_xor(acc, 2, 64);
  acc += __shfl_xor(acc, 1, 64);
  if (lane == 0) {
    C[wave_id] = __float2half(acc);
  }
}

__global__ __launch_bounds__(512) void wave_dot_split2_kernel(
    const __half* A,
    const __half* B,
    __half* C,
    int M,
    int N,
    int K) {
  const int wave_id = (blockIdx.x * blockDim.x + threadIdx.x) >> 6;
  const int lane = threadIdx.x & 63;
  const int wave = threadIdx.x >> 6;
  if (wave_id >= M * N * 2) {
    return;
  }

  const int output = wave_id >> 1;
  const int split = wave_id & 1;
  const int row = output / N;
  const int col = output % N;
  const __half* a_row = A + static_cast<int64_t>(row) * K;
  const __half* b_row = B + static_cast<int64_t>(col) * K;
  const int k_start = split * (K >> 1);
  const int k_end = k_start + (K >> 1);
  float acc = 0.0f;

  for (int base = k_start; base < k_end; base += 512) {
    const int offset = base + lane * 8;
    const uint4 a_raw = *reinterpret_cast<const uint4*>(a_row + offset);
    const uint4 b_raw = *reinterpret_cast<const uint4*>(b_row + offset);
    const __half2* a_half = reinterpret_cast<const __half2*>(&a_raw);
    const __half2* b_half = reinterpret_cast<const __half2*>(&b_raw);
    #pragma unroll
    for (int pair = 0; pair < 4; ++pair) {
      const float2 a = __half22float2(a_half[pair]);
      const float2 b = __half22float2(b_half[pair]);
      acc += a.x * b.x + a.y * b.y;
    }
  }

  acc += __shfl_xor(acc, 32, 64);
  acc += __shfl_xor(acc, 16, 64);
  acc += __shfl_xor(acc, 8, 64);
  acc += __shfl_xor(acc, 4, 64);
  acc += __shfl_xor(acc, 2, 64);
  acc += __shfl_xor(acc, 1, 64);

  __shared__ float partials[8];
  if (lane == 0) {
    partials[wave] = acc;
  }
  __syncthreads();
  if (lane == 0 && (wave & 1) == 0) {
    C[output] = __float2half(partials[wave] + partials[wave + 1]);
  }
}

template <int SPLITS>
__global__ __launch_bounds__(SPLITS * 64) void wave_split_rows_kernel(
    const __half* A,
    const __half* B,
    __half* C,
    int M,
    int N,
    int K) {
  const int col = blockIdx.x;
  const int row_base = blockIdx.y * 8;
  const int wave = threadIdx.x >> 6;
  const int lane = threadIdx.x & 63;
  const int k_length = K / SPLITS;
  const int k_base = wave * k_length;
  const int k_end = k_base + k_length;

  float acc[8];
  #pragma unroll
  for (int row = 0; row < 8; ++row) {
    acc[row] = 0.0f;
  }

  const __half* b_row = B + static_cast<int64_t>(col) * K;
  for (int offset = k_base + lane * 4; offset + 3 < k_end; offset += 256) {
    const uint2 b_raw = *reinterpret_cast<const uint2*>(b_row + offset);
    const __half2* b_half = reinterpret_cast<const __half2*>(&b_raw);
    const float2 b0 = __half22float2(b_half[0]);
    const float2 b1 = __half22float2(b_half[1]);

    #pragma unroll
    for (int row = 0; row < 8; ++row) {
      const int global_row = row_base + row;
      if (global_row < M) {
        const uint2 a_raw = *reinterpret_cast<const uint2*>(
            A + static_cast<int64_t>(global_row) * K + offset);
        const __half2* a_half = reinterpret_cast<const __half2*>(&a_raw);
        const float2 a0 = __half22float2(a_half[0]);
        const float2 a1 = __half22float2(a_half[1]);
        acc[row] += a0.x * b0.x + a0.y * b0.y;
        acc[row] += a1.x * b1.x + a1.y * b1.y;
      }
    }
  }

  #pragma unroll
  for (int row = 0; row < 8; ++row) {
    acc[row] += __shfl_xor(acc[row], 32, 64);
    acc[row] += __shfl_xor(acc[row], 16, 64);
    acc[row] += __shfl_xor(acc[row], 8, 64);
    acc[row] += __shfl_xor(acc[row], 4, 64);
    acc[row] += __shfl_xor(acc[row], 2, 64);
    acc[row] += __shfl_xor(acc[row], 1, 64);
  }

  __shared__ float partials[SPLITS][8];
  if (lane == 0) {
    #pragma unroll
    for (int row = 0; row < 8; ++row) {
      partials[wave][row] = acc[row];
    }
  }
  __syncthreads();

  if (threadIdx.x < 8) {
    const int row = row_base + threadIdx.x;
    if (row < M) {
      float total = 0.0f;
      #pragma unroll
      for (int part = 0; part < SPLITS; ++part) {
        total += partials[part][threadIdx.x];
      }
      C[static_cast<int64_t>(row) * N + col] = __float2half(total);
    }
  }
}

