__global__ __launch_bounds__(1024) void split_k16_kernel(
    const __half* A,
    const __half* B,
    __half* C,
    int M,
    int N,
    int K) {
  const int col = blockIdx.x;
  const int row_base = blockIdx.y * 8;
  const int wave = threadIdx.x >> 6;
  const int lane = threadIdx.x & 63;
  const int k_length = K >> 4;
  const int k_base = wave * k_length;
  const int k_end = k_base + k_length;

  float acc[8];
  #pragma unroll
  for (int row = 0; row < 8; ++row) {
    acc[row] = 0.0f;
  }

  for (int offset = k_base + (lane << 1); offset + 1 < k_end;
       offset += 128) {
    const __half2 b_half = *reinterpret_cast<const __half2*>(
        B + static_cast<int64_t>(col) * K + offset);
    const float2 b = __half22float2(b_half);

    #pragma unroll
    for (int row = 0; row < 8; ++row) {
      const int global_row = row_base + row;
      if (global_row < M) {
        const __half2 a_half = *reinterpret_cast<const __half2*>(
            A + static_cast<int64_t>(global_row) * K + offset);
        const float2 a = __half22float2(a_half);
        acc[row] += a.x * b.x + a.y * b.y;
      }
    }
  }

  #pragma unroll
  for (int row = 0; row < 8; ++row) {
    acc[row] += __shfl_xor(acc[row], 32, 64);
    acc[row] += __shfl_xor(acc[row], 16, 64);
    acc[row] += __shfl_xor(acc[row], 8, 64);
    acc[row] += __shfl_xor(acc[row], 4, 64);
    acc[row] += __shfl_xor(acc[row], 2, 64);
    acc[row] += __shfl_xor(acc[row], 1, 64);
  }

  __shared__ float partials[16][8];
  if (lane == 0) {
    #pragma unroll
    for (int row = 0; row < 8; ++row) {
      partials[wave][row] = acc[row];
    }
  }
  __syncthreads();

  if (threadIdx.x < 8) {
    const int row = row_base + threadIdx.x;
    if (row < M) {
      float total = 0.0f;
      #pragma unroll
      for (int part = 0; part < 16; ++part) {
        total += partials[part][threadIdx.x];
      }
      C[static_cast<int64_t>(row) * N + col] =
          __float2half(total);
    }
  }
}

