template <int ROWS>
__global__ __launch_bounds__(64) void small_full_k_kernel(
    const __half* __restrict__ A,
    const __half* __restrict__ B,
    __half* __restrict__ C) {
  using uint4_vector = __attribute__((__vector_size__(16))) unsigned int;
  const int col = blockIdx.x;
  if (col >= 128) {
    return;
  }
  const int lane = threadIdx.x;
  const __half* b_row = B + col * 2048;
  uint4 a_raw[ROWS][4];
  uint4_vector b_raw[4];
  float acc[ROWS];
  #pragma unroll
  for (int row = 0; row < ROWS; ++row) {
    acc[row] = 0.0f;
  }

  #pragma unroll
  for (int chunk = 0; chunk < 4; ++chunk) {
    const int offset = chunk * 512 + lane * 8;
    b_raw[chunk] = __builtin_nontemporal_load(
        reinterpret_cast<const uint4_vector*>(b_row + offset));
    #pragma unroll
    for (int row = 0; row < ROWS; ++row) {
      a_raw[row][chunk] = *reinterpret_cast<const uint4*>(
          A + row * 2048 + offset);
    }
  }

  #pragma unroll
  for (int chunk = 0; chunk < 4; ++chunk) {
    const uint32_t* b_words = reinterpret_cast<const uint32_t*>(
        &b_raw[chunk]);
    #pragma unroll
    for (int row = 0; row < ROWS; ++row) {
      const uint32_t* a_words = reinterpret_cast<const uint32_t*>(
          &a_raw[row][chunk]);
      #pragma unroll
      for (int pair = 0; pair < 4; ++pair) {
        asm volatile(
            "v_dot2c_f32_f16 %0, %2, %3"
            : "=v"(acc[row])
            : "0"(acc[row]), "v"(a_words[pair]), "v"(b_words[pair]));
      }
    }
  }

  #pragma unroll
  for (int row = 0; row < ROWS; ++row) {
    if constexpr (ROWS == 1) {
      acc[row] += __shfl_xor(acc[row], 32, 64);
      acc[row] += __shfl_xor(acc[row], 16, 64);
      acc[row] += __shfl_xor(acc[row], 8, 64);
      acc[row] += __shfl_xor(acc[row], 4, 64);
      acc[row] += __shfl_xor(acc[row], 2, 64);
      acc[row] += __shfl_xor(acc[row], 1, 64);
    } else {
      asm volatile(
          "s_nop 0\n\tv_add_f32 %0, %2, %3 row_shr:8 bound_ctrl:0"
          : "=v"(acc[row]) : "0"(acc[row]), "v"(acc[row]), "v"(acc[row]));
      asm volatile(
          "s_nop 0\n\tv_add_f32 %0, %2, %3 row_shr:4 bound_ctrl:0"
          : "=v"(acc[row]) : "0"(acc[row]), "v"(acc[row]), "v"(acc[row]));
      asm volatile(
          "s_nop 0\n\tv_add_f32 %0, %2, %3 row_shr:2 bound_ctrl:0"
          : "=v"(acc[row]) : "0"(acc[row]), "v"(acc[row]), "v"(acc[row]));
      asm volatile(
          "s_nop 0\n\tv_add_f32 %0, %2, %3 wave_shr:1 bound_ctrl:0"
          : "=v"(acc[row]) : "0"(acc[row]), "v"(acc[row]), "v"(acc[row]));
      asm volatile(
          "s_nop 0\n\tv_add_f32 %0, %2, %3 row_bcast:15 bound_ctrl:0"
          : "=v"(acc[row]) : "0"(acc[row]), "v"(acc[row]), "v"(acc[row]));
      asm volatile(
          "s_nop 0\n\tv_add_f32 %0, %2, %3 row_bcast:31 bound_ctrl:0"
          : "=v"(acc[row]) : "0"(acc[row]), "v"(acc[row]), "v"(acc[row]));
    }
  }

  if (lane == 63) {
    #pragma unroll
    for (int row = 0; row < ROWS; ++row) {
      C[row * 128 + col] = __float2half(acc[row]);
    }
  }
}

#define SMALL_FULL_K_CASE(ROWS_)                                              \
  case ROWS_:                                                                 \
    small_full_k_kernel<ROWS_><<<256, 64, 0, stream>>>(                       \
        static_cast<const __half*>(A), static_cast<const __half*>(B),         \
        static_cast<__half*>(C));                                             \
    break;

extern "C" void launch_small_full_k(
    const void* A,
    const void* B,
    void* C,
    int M,
    cudaStream_t stream) {
  switch (M) {
    SMALL_FULL_K_CASE(1)
    SMALL_FULL_K_CASE(2)
    SMALL_FULL_K_CASE(3)
    SMALL_FULL_K_CASE(4)
    SMALL_FULL_K_CASE(5)
    SMALL_FULL_K_CASE(6)
    SMALL_FULL_K_CASE(7)
    SMALL_FULL_K_CASE(8)
    SMALL_FULL_K_CASE(9)
    SMALL_FULL_K_CASE(10)
    SMALL_FULL_K_CASE(11)
    SMALL_FULL_K_CASE(12)
    SMALL_FULL_K_CASE(13)
    SMALL_FULL_K_CASE(14)
    SMALL_FULL_K_CASE(15)
    SMALL_FULL_K_CASE(16)
    SMALL_FULL_K_CASE(17)
    SMALL_FULL_K_CASE(18)
    SMALL_FULL_K_CASE(19)
    SMALL_FULL_K_CASE(20)
    SMALL_FULL_K_CASE(21)
    SMALL_FULL_K_CASE(22)
    SMALL_FULL_K_CASE(23)
    SMALL_FULL_K_CASE(24)
    SMALL_FULL_K_CASE(25)
    SMALL_FULL_K_CASE(26)
    default:
      small_full_k_kernel<2><<<256, 64, 0, stream>>>(
          static_cast<const __half*>(A), static_cast<const __half*>(B),
