      break;
  }
}

__global__ __launch_bounds__(128) void wave_tile4_kernel(
    const __half* A,
    const __half* B,
    __half* C,
    int M,
    int N,
    int K) {
  const int wave_id = (blockIdx.x * blockDim.x + threadIdx.x) >> 6;
  const int col_tiles = (N + 3) >> 2;
  const int row_tile = wave_id / col_tiles;
  const int col_tile = wave_id % col_tiles;
  const int row_base = row_tile * 4;
  const int col_base = col_tile * 4;
  const int lane = threadIdx.x & 63;

  float acc[4][4];
  #pragma unroll
  for (int i = 0; i < 4; ++i) {
    #pragma unroll
    for (int j = 0; j < 4; ++j) {
      acc[i][j] = 0.0f;
    }
  }

  for (int base = 0; base < K; base += 512) {
    const int offset = base + lane * 8;
    uint4 a_raw[4];
    uint4 b_raw[4];
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
      const int row = row_base + i;
      if (row < M) {
        a_raw[i] = *reinterpret_cast<const uint4*>(
            A + static_cast<int64_t>(row) * K + offset);
      } else {
        a_raw[i] = make_uint4(0, 0, 0, 0);
      }
    }
    #pragma unroll
    for (int j = 0; j < 4; ++j) {
      const int col = col_base + j;
      if (col < N) {
        b_raw[j] = *reinterpret_cast<const uint4*>(
            B + static_cast<int64_t>(col) * K + offset);
      } else {
        b_raw[j] = make_uint4(0, 0, 0, 0);
      }
    }

    float2 a_values[4][4];
    float2 b_values[4][4];
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
      const __half2* halves = reinterpret_cast<const __half2*>(&a_raw[i]);
      #pragma unroll
      for (int pair = 0; pair < 4; ++pair) {
        a_values[i][pair] = __half22float2(halves[pair]);
      }
    }
    #pragma unroll
    for (int j = 0; j < 4; ++j) {
      const __half2* halves = reinterpret_cast<const __half2*>(&b_raw[j]);
      #pragma unroll
      for (int pair = 0; pair < 4; ++pair) {
        b_values[j][pair] = __half22float2(halves[pair]);
      }
    }

    #pragma unroll
    for (int i = 0; i < 4; ++i) {
      #pragma unroll
      for (int j = 0; j < 4; ++j) {
        float sum = 0.0f;
        #pragma unroll
        for (int pair = 0; pair < 4; ++pair) {
          sum += a_values[i][pair].x * b_values[j][pair].x;
          sum += a_values[i][pair].y * b_values[j][pair].y;
        }
        acc[i][j] += sum;
      }
    }
  }

  #pragma unroll
  for (int i = 0; i < 4; ++i) {
    #pragma unroll
    for (int j = 0; j < 4; ++j) {
      acc[i][j] += __shfl_xor(acc[i][j], 32, 64);
      acc[i][j] += __shfl_xor(acc[i][j], 16, 64);
      acc[i][j] += __shfl_xor(acc[i][j], 8, 64);
      acc[i][j] += __shfl_xor(acc[i][j], 4, 64);
      acc[i][j] += __shfl_xor(acc[i][j], 2, 64);
      acc[i][j] += __shfl_xor(acc[i][j], 1, 64);
    }
  }

  if (lane == 0) {
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
      const int row = row_base + i;
      if (row >= M) {
        continue;
      }
      #pragma unroll
      for (int j = 0; j < 4; ++j) {
        const int col = col_base + j;
        if (col < N) {
          C[static_cast<int64_t>(row) * N + col] =
              __float2half(acc[i][j]);
        }
      }
    }
  }
}

