#include <string>
#include <vector>

namespace {

constexpr size_t workspace_bytes = 256 * 1024 * 1024;

hipblasLtHandle_t handle;
void* workspace = nullptr;

struct GemmPlan {
    bool valid;
    hipblasLtMatmulDesc_t op;
    hipblasLtMatrixLayout_t a;
    hipblasLtMatrixLayout_t b;
    hipblasLtMatrixLayout_t c;
    hipblasLtMatmulHeuristicResult_t algorithm;
};

std::map<std::array<int64_t, 4>, GemmPlan> plans;

void check(hipblasStatus_t status, const char* message) {
    if (status != HIPBLAS_STATUS_SUCCESS) {
        throw std::runtime_error(std::string(message) + ": " +
                                 hipblasStatusToString(status));
    }
}

GemmPlan make_plan(int64_t M, int64_t N, int64_t K, int solution) {
    GemmPlan plan{};
    check(hipblasLtMatmulDescCreate(&plan.op, HIPBLAS_COMPUTE_32F, HIP_R_32F),
          "hipblasLtMatmulDescCreate");
    hipblasOperation_t transpose = HIPBLAS_OP_T;
    hipblasOperation_t no_transpose = HIPBLAS_OP_N;
    check(hipblasLtMatmulDescSetAttribute(
              plan.op, HIPBLASLT_MATMUL_DESC_TRANSA, &transpose, sizeof(int32_t)),
          "hipblasLtMatmulDescSetAttribute");
    check(hipblasLtMatmulDescSetAttribute(
              plan.op, HIPBLASLT_MATMUL_DESC_TRANSB, &no_transpose,
              sizeof(int32_t)),
          "hipblasLtMatmulDescSetAttribute");
    check(hipblasLtMatrixLayoutCreate(&plan.a, HIP_R_16F, K, N, K),
          "hipblasLtMatrixLayoutCreate");
    check(hipblasLtMatrixLayoutCreate(&plan.b, HIP_R_16F, K, M, K),
          "hipblasLtMatrixLayoutCreate");
    check(hipblasLtMatrixLayoutCreate(&plan.c, HIP_R_16F, N, M, N),
          "hipblasLtMatrixLayoutCreate");

    std::vector<int> indices{solution};
    std::vector<hipblasLtMatmulHeuristicResult_t> algorithms;
    check(hipblaslt_ext::getAlgosFromIndex(handle, indices, algorithms),
          "hipblaslt_ext::getAlgosFromIndex");
    if (algorithms.size() != 1) {
        throw std::runtime_error("hipBLASLt returned no algorithm");
    }
    plan.algorithm = algorithms[0];
    float one = 1.0f;
    float zero = 0.0f;
    size_t required_workspace_bytes = 0;
    hipblasStatus_t supported = hipblaslt_ext::matmulIsAlgoSupported(
        handle, plan.op, &one, plan.a, plan.b, &zero, plan.c, plan.c,
        plan.algorithm.algo, required_workspace_bytes);
    if (supported != HIPBLAS_STATUS_SUCCESS ||
        required_workspace_bytes > workspace_bytes) {
        hipblasLtMatrixLayoutDestroy(plan.a);
        hipblasLtMatrixLayoutDestroy(plan.b);
        hipblasLtMatrixLayoutDestroy(plan.c);
        hipblasLtMatmulDescDestroy(plan.op);
        return GemmPlan{};
    }
    plan.valid = true;
    return plan;
}

}

int64_t solution_for(int64_t M) {
    if (M >= 193) return 478654;
    if (M >= 129) return 477998;
    if (M >= 65) return 477978;
    if (M >= 33) return 478208;
    if (M >= 17) return 478220;
    return 478219;
}

void initialize() {
    if (!workspace) {
        check(hipblasLtCreate(&handle), "hipblasLtCreate");
        if (hipMalloc(&workspace, workspace_bytes) != hipSuccess) {
            throw std::runtime_error("failed to allocate hipBLASLt workspace");
        }
    }
}

torch::Tensor gemm(torch::Tensor A, torch::Tensor B) {
    const bool supported = A.dim() == 2 && B.dim() == 2 &&
                           A.is_contiguous() && B.is_contiguous() &&
                           A.scalar_type() == at::kHalf &&
                           B.scalar_type() == at::kHalf;
    if (!supported) {
        if (B.dim() == 2) {
            return at::matmul(A, B.transpose(1, 0));
        }
        return at::matmul(A, B);
    }
    const int64_t M = A.size(0);
    const int64_t N = B.size(0);
    const int64_t K = A.size(1);
    if (B.size(1) != K || M == 0 || N == 0 || K == 0) {
        return at::matmul(A, B.transpose(1, 0));
    }
    if (!workspace) {
        initialize();
    }

    const int64_t solution = solution_for(M);
    const std::array<int64_t, 4> key{M, N, K, solution};
    auto plan = plans.find(key);
    if (plan == plans.end()) {
        plan = plans.emplace(
            key, make_plan(M, N, K, static_cast<int>(solution))).first;
    }
    if (!plan->second.valid) {
        return at::matmul(A, B.transpose(1, 0));
    }

    auto result = at::detail::empty_cuda(
        {M, N}, at::kHalf, A.device(), c10::MemoryFormat::Contiguous);
    float one = 1.0f;
    float zero = 0.0f;
    auto stream = at::cuda::getCurrentHIPStream().stream();
    check(hipblasLtMatmul(handle, plan->second.op, &one, B.data_ptr(),
                          plan->second.a, A.data_ptr(), plan->second.b, &zero,
                          result.data_ptr(), plan->second.c, result.data_ptr(),
                          plan->second.c, &plan->second.algorithm.algo,
                          workspace, workspace_bytes, stream),
          "hipblasLtMatmul");
    return result;
}
