torch::Tensor post_norm_residual(
    torch::Tensor input,
    torch::Tensor residual,
    torch::Tensor weight,
    double epsilon) {
    const bool supported = input.is_cuda() && input.is_contiguous() &&
        residual.is_contiguous() && weight.is_contiguous() &&
        input.scalar_type() == at::kBFloat16 &&
        residual.scalar_type() == at::kBFloat16 &&
        weight.scalar_type() == at::kBFloat16 &&
        residual.sizes() == input.sizes() &&
        weight.numel() == input.size(-1);
    const bool aligned = input.size(-1) != 4096 ||
        ((reinterpret_cast<uintptr_t>(input.data_ptr()) |
          reinterpret_cast<uintptr_t>(residual.data_ptr()) |
          reinterpret_cast<uintptr_t>(weight.data_ptr())) & 15) == 0;
    if (!supported || !aligned) {
        auto normalized = input.to(at::kFloat);
        auto variance = normalized.pow(2).mean(-1, true);
        normalized = normalized * at::rsqrt(variance + epsilon);
        normalized = weight.to(at::kFloat) * normalized;
        return residual + normalized.to(input.scalar_type());
