    const int hidden_size = input.size(-1);

    const long rows = input.numel() / hidden_size;
    auto output = at::Tensor(at::detail::empty_cuda(
        input.sizes(), input.scalar_type(), input.device(), std::nullopt));
    if (rows == 0) return output;
