    auto stream = at::cuda::getCurrentCUDAStream();
    auto input_pointer = reinterpret_cast<const __hip_bfloat16*>(input.data_ptr());
    auto residual_pointer = reinterpret_cast<const __hip_bfloat16*>(residual.data_ptr());
    auto weight_pointer = reinterpret_cast<const __hip_bfloat16*>(weight.data_ptr());
    auto output_pointer = reinterpret_cast<__hip_bfloat16*>(output.data_ptr());
    if (use_nontemporal) {
        post_norm_residual_kernel<true><<<rows, kThreads, 0, stream>>>(
            input_pointer, residual_pointer, weight_pointer, output_pointer,
            rows, hidden_size, static_cast<float>(epsilon));
